draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figures
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 120);
  ctx.lineTo(W/4 - 30, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 120);
  ctx.lineTo(W/4 + 30, H/2 + 150);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 120);
  ctx.lineTo(W - W/4 - 30, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 120);
  ctx.lineTo(W - W/4 + 30, H/2 + 150);
  ctx.stroke();

  // connection line
  ctx.beginPath();
  ctx.moveTo(W/2 - 50 + 30 * Math.sin(t), H/2 + 50);
  ctx.lineTo(W/2 + 50 + 30 * Math.cos(t), H/2 + 50);
  ctx.stroke();

  ctx.restore();
}
